def _mul_backward_linear_offset(index, shape: tl.constexpr, strides: tl.constexpr):
    offset = 0
    for dim in tl.static_range(len(shape.value) - 1, -1, -1):
        coordinate = index % shape.value[dim]
        index //= shape.value[dim]
        offset += coordinate * strides.value[dim]
    return offset


@triton.jit
def _mul_backward_grad_one(
    pid,
    grad_output_ptr,
    other_ptr,
    grad_input_ptr,
    n_elements,
    reduction_elements,
    target_shape: tl.constexpr,
    target_divs: tl.constexpr,
    output_strides: tl.constexpr,
    fixed_divs: tl.constexpr,
    fixed_sizes: tl.constexpr,
    reduction_divs: tl.constexpr,
    reduction_sizes: tl.constexpr,
    other_strides: tl.constexpr,
    grad_strides: tl.constexpr,
    GRAD_COMPLEX: tl.constexpr,
    OTHER_COMPLEX: tl.constexpr,
    TARGET_COMPLEX: tl.constexpr,
    BLOCK_REDUCE: tl.constexpr,
):
    if pid < n_elements:
        output_offset = 0
        for dim in tl.static_range(len(target_shape.value)):
            output_coordinate = (pid // target_divs.value[dim]) % target_shape.value[
                dim
            ]
            output_offset += output_coordinate * output_strides.value[dim]

        total_real = 0.0
        total_imag = 0.0
        start = 0
        while start < reduction_elements:
            reduction_index = start + tl.arange(0, BLOCK_REDUCE)
            mask = reduction_index < reduction_elements
            other_offset = tl.zeros((BLOCK_REDUCE,), dtype=tl.int64)
            grad_offset = tl.zeros((BLOCK_REDUCE,), dtype=tl.int64)

            for dim in tl.static_range(len(fixed_divs.value)):
                fixed_coordinate = (pid // fixed_divs.value[dim]) % fixed_sizes.value[
                    dim
                ]
                reduction_coordinate = (
                    reduction_index // reduction_divs.value[dim]
                ) % reduction_sizes.value[dim]
                common_coordinate = fixed_coordinate + reduction_coordinate
                other_offset += common_coordinate * other_strides.value[dim]
                grad_offset += common_coordinate * grad_strides.value[dim]

            grad_real = tl.load(grad_output_ptr + grad_offset, mask=mask, other=0.0)
            grad_imag = tl.zeros((BLOCK_REDUCE,), tl.float32)
            if GRAD_COMPLEX:
                grad_imag = tl.load(
                    grad_output_ptr + grad_offset + 1, mask=mask, other=0.0
                )
            other_real = tl.load(other_ptr + other_offset, mask=mask, other=0.0)
            other_imag = tl.zeros((BLOCK_REDUCE,), tl.float32)
            if OTHER_COMPLEX:
                other_imag = tl.load(other_ptr + other_offset + 1, mask=mask, other=0.0)

            # grad * conj(other), with real projection for real-valued inputs.
            product_real = grad_real * other_real + grad_imag * other_imag
            product_imag = grad_imag * other_real - grad_real * other_imag
            total_real += tl.sum(product_real, axis=0)
            total_imag += tl.sum(product_imag, axis=0)
            start += BLOCK_REDUCE

        tl.store(grad_input_ptr + output_offset, total_real)
        if TARGET_COMPLEX:
            tl.store(grad_input_ptr + output_offset + 1, total_imag)


